    tbl_h: 'Projekte {in}: Genehmigung, Übergabe-Verlauf und Bilanz des Bauträgers', tbl_p: 'Die drei Angaben, die Portale selten zeigen, nebeneinander für {k} Projekte. Jede Projektseite nennt alle Quellen.',
    th_proj: 'Projekt', th_dev: 'Bauträger', th_permit: 'Genehmigungsnummer', th_rec: 'Übergabe-Verlauf', th_devrec: 'Bilanz des Bauträgers in unseren Daten', np: 'Nicht veröffentlicht', pubd: 'Veröffentlicht',
